{
  "tool": "hr_helpdesk.search_knowledge_base",
  "query": "research paper draft submission deadline extension",
  "results": [
    {
      "id": "kb-1042",
      "title": "Guidelines for submitting a research paper draft for internal review",
      "snippet": "Drafts should be submitted via the Research Portal by the 15th of each month. Extensions can be requested from the Research Office at least five business days before the deadline. Include the title, authors, and a 200-word abstract with your submission.",
      "url": "https://intranet.novacorp.com/hr/kb/1042",
      "updated": "2025-03-10"
    },
    {
      "id": "kb-2098",
      "title": "Using the HR chatbot for research funding queries",
      "snippet": "The HR virtual assistant can answer questions about funding opportunities and submission timelines. Type 'research funding' in the chat window to get started. For complex cases, it will create a ticket for a human advisor.",
      "url": "https://intranet.novacorp.com/hr/kb/2098",
      "updated": "2025-02-28"
    }
  ],
  "total": 2
}

{
  "ticket_id": "FIN-7721",
  "subject": "Lost parcel - reimbursement request",
  "status": "open",
  "priority": "medium",
  "description": "I ordered a book from an online retailer, but the parcel was lost in transit. The courier's tracking shows it was delivered to the mailroom, but it's not there. I need to file a reimbursement claim. Please advise on the process.",
  "comments": [
    {
      "author": "finance.helpdesk",
      "timestamp": "2025-03-25T10:15:00Z",
      "text": "We have received your request. To proceed, please provide the order number and proof of purchase. You can upload documents via the Finance Portal. Our chatbot is available 24/7 for status updates."
    },
    {
      "author": "employee.jdoe",
      "timestamp": "2025-03-25T11:30:00Z",
      "text": "Order number is #ORD-5566. I've attached the receipt. The chatbot said I should also include a signed declaration of non-receipt; is that necessary?"
    }
  ]
}
